/**
 * POST /api/threshold/mcp — the metaMe Threshold Gateway (PRD-THR-001 §8).
 *
 * Minimal MCP server over Streamable HTTP. Threshold bearer authority is
 * resolved once at the transport boundary. Upload execution uses the same
 * shared executor as the native connector action so the two interfaces cannot
 * drift onto different authentication/storage paths again.
 */

import { NextRequest, NextResponse } from 'next/server';
import { publicOrigin } from '@/utils/publicOrigin';
import {
  SERVER_INFO,
  PROTOCOL_VERSION,
  HANDSHAKE_TOOLS,
  listTools,
  listResources,
  listPrompts,
  getPrompt,
  callTool,
  readResource,
  type GatewayContext,
} from '@/services/threshold/gateway';
import { resolveInvitation } from '@/services/threshold/resolveInvitation';
import { resolveBearer, createUpgradeHandshake, hasScope } from '@/services/threshold/gatewaySession';
import { makeIrlAdapter } from '@/services/threshold/irlAdapter';
import { makePublicKnowledgeAdapter } from '@/services/threshold/publicKnowledge';
import { buildCompanionInstallBrief } from '@/services/companion/extensionArtifact';
import { getSupabaseServer } from '@/app/api/_lib/supabaseServer';
import { resolveConstitutionalNavigatorState } from '@/services/threshold/constitutionalNavigator';
import {
  getAccessibleIQube,
  listAccessibleIQubes,
  readAccessibleIQubeText,
} from '@/services/threshold/personaIQubeProjection';
import {
  getExchangeStateForMcp,
  depositExchangeArtifactViaMcp,
  confirmOperatorAssistedArtifactViaMcp,
  declareArtifactFreezeViaMcp,
  signExchangeInstrumentViaMcp,
  establishDelegationViaMcp,
  resolveExchangeWriteAuthority,
} from '@/services/threshold/mcpConstitutionalActs';
import {
  executeThresholdContentUpload,
  THRESHOLD_UPLOAD_ROLES,
  decodeBase64Strict,
  assertDecodableImage,
} from '@/services/threshold/uploadContentAsset';
import {
  getPersonaState,
  listAvailablePersonas,
  requestPersonaSwitch,
} from '@/services/threshold/personaRecross';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 300;

function cors(res: NextResponse): NextResponse {
  res.headers.set('Access-Control-Allow-Origin', '*');
  res.headers.set('Access-Control-Allow-Methods', 'POST, GET, OPTIONS');
  res.headers.set('Access-Control-Allow-Headers', 'content-type, mcp-session-id, mcp-protocol-version, authorization');
  res.headers.set('Cache-Control', 'no-store');
  return res;
}

export async function OPTIONS() {
  return cors(new NextResponse(null, { status: 204 }));
}

export async function GET() {
  return cors(NextResponse.json({ error: 'Use POST for JSON-RPC; this gateway is stateless.' }, { status: 405 }));
}

interface RpcMsg { jsonrpc?: string; id?: string | number | null; method?: string; params?: Record<string, unknown> }

function ok(id: RpcMsg['id'], result: unknown) {
  return { jsonrpc: '2.0', id: id ?? null, result };
}
function err(id: RpcMsg['id'], code: number, message: string) {
  return { jsonrpc: '2.0', id: id ?? null, error: { code, message } };
}

function inferMime(fileName: string): string {
  const lower = fileName.toLowerCase();
  if (lower.endsWith('.jpg') || lower.endsWith('.jpeg')) return 'image/jpeg';
  if (lower.endsWith('.png')) return 'image/png';
  if (lower.endsWith('.webp')) return 'image/webp';
  if (lower.endsWith('.gif')) return 'image/gif';
  if (lower.endsWith('.pdf')) return 'application/pdf';
  if (lower.endsWith('.md')) return 'text/markdown';
  if (lower.endsWith('.txt')) return 'text/plain';
  if (lower.endsWith('.json')) return 'application/json';
  if (lower.endsWith('.docx')) return 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
  if (lower.endsWith('.mp4')) return 'video/mp4';
  if (lower.endsWith('.webm')) return 'video/webm';
  if (lower.endsWith('.mp3')) return 'audio/mpeg';
  if (lower.endsWith('.wav')) return 'audio/wav';
  return 'application/octet-stream';
}

async function callUploadContentAsset(args: Record<string, unknown>, ctx: GatewayContext) {
  const session = ctx.session;
  if (!session || !hasScope(session, 'content.asset.upload')) {
    return {
      isError: true,
      content: [{ type: 'text', text: 'content.asset.upload capability required' }],
    };
  }

  const fileBase64 = typeof args.fileBase64 === 'string' ? args.fileBase64 : null;
  const file = typeof args.file === 'string' ? args.file : null;
  if ((fileBase64 && file) || (!fileBase64 && !file)) {
    return {
      isError: true,
      content: [{ type: 'text', text: 'Exactly one of fileBase64 or file is required.' }],
    };
  }

  const fileName = typeof args.fileName === 'string' ? args.fileName.trim() : '';
  const domain = typeof args.domain === 'string' ? args.domain.trim() : '';
  const role = typeof args.role === 'string' ? args.role.trim() : '';
  if (!fileName || !domain || !role) {
    return {
      isError: true,
      content: [{ type: 'text', text: 'Missing required parameters: fileName, domain, role' }],
    };
  }
  if (!THRESHOLD_UPLOAD_ROLES.has(role)) {
    return {
      isError: true,
      content: [{ type: 'text', text: `Invalid role: ${role}` }],
    };
  }

  try {
    // Strict decode: rejects a data-URL prefix, whitespace, or any non-base64
    // character loudly instead of silently truncating to whatever Node's
    // lenient decoder could salvage. A corrupt decode here previously
    // persisted a garbage buffer all the way to Autonomys with no error
    // anywhere in the pipeline — the failure only surfaced later, as an
    // undecodable image on the display side.
    const bytes = decodeBase64Strict(fileBase64 || file || '');

    // Image-bearing roles must be genuine, fully-decodable rasters before
    // they are ever encrypted and persisted — this is the one point where
    // the original source is still in hand to validate against.
    await assertDecodableImage(bytes, role);

    const receipt = await executeThresholdContentUpload({
      bytes,
      mimeType: inferMime(fileName),
      fileName,
      domain,
      role,
      origin: ctx.origin,
      contentId: typeof args.contentId === 'string' ? args.contentId : null,
      bind: args.bind !== false,
      bundleId: typeof args.bundleId === 'string' ? args.bundleId : null,
      bundleLabel: typeof args.bundleLabel === 'string' ? args.bundleLabel : null,
      bundleType: typeof args.bundleType === 'string' ? args.bundleType : null,
      bundleOrder: typeof args.bundleOrder === 'number' ? args.bundleOrder : null,
      assetUse: typeof args.assetUse === 'string' ? args.assetUse : null,
      setPrimary: args.setPrimary === true,
    });

    return {
      content: [{ type: 'text', text: JSON.stringify(receipt) }],
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : 'upload-failed';
    console.error('[threshold/mcp] upload_content_asset failed:', message);
    return {
      isError: true,
      content: [{ type: 'text', text: `Upload failed: ${message}` }],
    };
  }
}

async function handleOne(msg: RpcMsg, ctx: GatewayContext): Promise<object | null> {
  const { method, id, params = {} } = msg;
  if (id === undefined || id === null) return null;

  try {
    switch (method) {
      case 'initialize':
        return ok(id, {
          protocolVersion: typeof params.protocolVersion === 'string' ? params.protocolVersion : PROTOCOL_VERSION,
          capabilities: { tools: {}, resources: {}, prompts: {} },
          serverInfo: SERVER_INFO,
          instructions:
            'metaMe Threshold Gateway. Read metame://agent-manifest first to reconstruct the constitutional architecture, source precedence, MCP exposure, and access boundaries. Inspect a Threshold Link when present. Only the human authorizes changes of authority.',
        });
      case 'ping':
        return ok(id, {});
      case 'tools/list':
        return ok(id, { tools: listTools() });
      case 'tools/call': {
        const name = String(params.name ?? '');
        const args = (params.arguments as Record<string, unknown>) ?? {};
        // Upload is intercepted at the transport boundary so both MCP and native
        // connector paths share one authorized execution function. This avoids an
        // authenticated MCP session making an unauthenticated internal HTTP hop.
        if (name === 'upload_content_asset') {
          return ok(id, await callUploadContentAsset(args, ctx));
        }
        return ok(id, await callTool(name, args, ctx));
      }
      case 'resources/list':
        return ok(id, { resources: listResources() });
      case 'resources/read':
        return ok(id, await readResource(String(params.uri ?? ''), ctx));
      case 'prompts/list':
        return ok(id, { prompts: listPrompts() });
      case 'prompts/get':
        return ok(id, getPrompt(String(params.name ?? ''), (params.arguments as Record<string, unknown>) ?? {}));
      default:
        return err(id, -32601, `Method not found: ${method}`);
    }
  } catch (e) {
    return err(id, -32603, e instanceof Error ? e.message : 'internal error');
  }
}

export async function POST(request: NextRequest) {
  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return cors(NextResponse.json(err(null, -32700, 'Parse error'), { status: 400 }));
  }

  const origin = publicOrigin(request);
  const authz = request.headers.get('authorization');
  const bearer = authz?.toLowerCase().startsWith('bearer ') ? authz.slice(7).trim() : null;
  const session = await resolveBearer(bearer);
  const irl = makeIrlAdapter(origin);
  const ctx: GatewayContext = {
    origin,
    gatewayUrl: `${origin}/api/threshold/mcp`,
    resolveInvitation,
    session,
    irl,
    // Unauthenticated by design — wired regardless of session, reusing the
    // SAME irl adapter instance above for its IRL OS branch.
    publicKnowledge: makePublicKnowledgeAdapter({ origin, irl }),
    companionInstall: () => buildCompanionInstallBrief(origin),
    beginServiceUpgrade: session
      ? async (service, missing) => {
          const hs = await createUpgradeHandshake({ parentSessionId: session.id, service, requestedScope: missing });
          if (!hs) return null;
          return { authorizeUrl: `${origin}/threshold/enter-service#code=${encodeURIComponent(hs.handshakeCode)}` };
        }
      : undefined,
    personaRecross: session
      ? {
          getState: () => getPersonaState(session),
          listAvailable: () => listAvailablePersonas(session),
          requestSwitch: (input) => requestPersonaSwitch(session, input, origin),
        }
      : undefined,
    resolveNavigatorState: session
      ? async (opts) => {
          const admin = getSupabaseServer();
          if (!admin) return null;
          return resolveConstitutionalNavigatorState(admin, session, opts);
        }
      : undefined,
    iqubeProjection: session
      ? {
          list: (query) => listAccessibleIQubes(session, query),
          get: (iqubeId) => getAccessibleIQube(session, iqubeId),
          readText: (iqubeId, opts) => readAccessibleIQubeText(session, iqubeId, opts),
        }
      : undefined,
    mcpActs: session
      ? {
          getExchangeState: () => {
            const admin = getSupabaseServer();
            if (!admin) return Promise.resolve({ ok: false as const, error: 'Platform database is unavailable.' });
            return getExchangeStateForMcp(admin, session);
          },
          depositArtifact: (args) => {
            const admin = getSupabaseServer();
            if (!admin) return Promise.resolve({ ok: false as const, error: 'Platform database is unavailable.' });
            return depositExchangeArtifactViaMcp(admin, session, args);
          },
          confirmOperatorAssistedArtifact: (args) => {
            const admin = getSupabaseServer();
            if (!admin) return Promise.resolve({ ok: false as const, error: 'Platform database is unavailable.' });
            return confirmOperatorAssistedArtifactViaMcp(admin, session, args);
          },
          declareFreeze: (args) => {
            const admin = getSupabaseServer();
            if (!admin) return Promise.resolve({ ok: false as const, error: 'Platform database is unavailable.' });
            return declareArtifactFreezeViaMcp(admin, session, args);
          },
          signInstrument: (args) => {
            const admin = getSupabaseServer();
            if (!admin) return Promise.resolve({ ok: false as const, error: 'Platform database is unavailable.' });
            return signExchangeInstrumentViaMcp(admin, session, args);
          },
          establishDelegation: (args) => {
            const admin = getSupabaseServer();
            if (!admin) return Promise.resolve({ ok: false as const, error: 'Platform database is unavailable.' });
            return establishDelegationViaMcp(admin, session, args);
          },
          resolveExchangeAuthority: () => {
            const admin = getSupabaseServer();
            if (!admin) return Promise.resolve({ ok: false as const, error: 'Platform database is unavailable.' });
            return resolveExchangeWriteAuthority(admin, session);
          },
        }
      : undefined,
  };

  if (!session) {
    const msgs = Array.isArray(body) ? body : [body];
    const wantsAuthTool = msgs.some(
      (m) =>
        (m as RpcMsg)?.method === 'tools/call' &&
        HANDSHAKE_TOOLS.has(String(((m as RpcMsg).params as Record<string, unknown> | undefined)?.name ?? '')),
    );
    if (wantsAuthTool) {
      const res = cors(NextResponse.json(err(null, -32001, 'Constitutional Handshake required'), { status: 401 }));
      res.headers.set(
        'WWW-Authenticate',
        `Bearer resource_metadata="${origin}/.well-known/oauth-protected-resource"`,
      );
      return res;
    }
  }

  if (Array.isArray(body)) {
    const responses = (await Promise.all(body.map((m) => handleOne(m as RpcMsg, ctx)))).filter(Boolean);
    if (responses.length === 0) return cors(new NextResponse(null, { status: 202 }));
    return cors(NextResponse.json(responses));
  }

  const response = await handleOne(body as RpcMsg, ctx);
  if (response === null) return cors(new NextResponse(null, { status: 202 }));
  return cors(NextResponse.json(response));
}

import { NextRequest, NextResponse } from 'next/server';
import { resolvePersonaOrTimeout, PERSONA_TIMEOUT_MESSAGE } from '@/app/api/dev-command-center/_lib/persona';
import { getPersonaSwitchHandshake, issueAuthorizationCode } from '@/services/threshold/gatewaySession';
import { resolveOwnedSwitchTarget, rootScopeForTarget, projectAvailablePersona } from '@/services/threshold/personaRecross';
import { getActivePersonaByPublicRef } from '@/services/identity/getActivePersona';
import { formAgreement, acceptAgreement, authorizeAgreement } from '@/services/constitutional/constitutionalAgreement';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

const FORBIDDEN_ACTIONS = ['publish', 'commit-funds', 'move-funds', 'delegate-agent', 'disclose-identity-credentials'];

export async function POST(request: NextRequest) {
  const principal = await resolvePersonaOrTimeout(request);
  if (principal.status === 'timeout') return NextResponse.json({ ok: false, error: PERSONA_TIMEOUT_MESSAGE }, { status: 503 });
  if (principal.status === 'unauthenticated') return NextResponse.json({ ok: false, error: 'unauthenticated' }, { status: 401 });
  const body = (await request.json().catch(() => null)) as Record<string, unknown> | null;
  const handshakeCode = typeof body?.handshakeCode === 'string' ? body.handshakeCode.trim() : '';
  const action = body?.action === 'authorize' ? 'authorize' : 'inspect';
  if (!handshakeCode) return NextResponse.json({ ok: false, error: 'handshakeCode required' }, { status: 400 });

  const handshake = await getPersonaSwitchHandshake(handshakeCode);
  if (!handshake) return NextResponse.json({ ok: false, error: 'persona switch not found or unavailable' }, { status: 404 });
  if (handshake.status !== 'pending') {
    return NextResponse.json({ ok: false, error: `persona switch is '${handshake.status}', not pending` }, { status: 409 });
  }
  if (handshake.expiresAt && new Date(handshake.expiresAt).getTime() < Date.now()) {
    return NextResponse.json({ ok: false, error: 'persona switch expired' }, { status: 410 });
  }
  // Persona switching is a fresh OAuth crossing, never an in-place session
  // mutation. A missing correlation state makes that crossing unusable for
  // external clients and must fail closed rather than issuing an uncorrelated
  // authorization code. Legacy pending rows without state must be restarted.
  if (!handshake.oauthState?.trim()) {
    return NextResponse.json({ ok: false, error: 'persona switch state missing; request a fresh crossing' }, { status: 409 });
  }

  const owned = await resolveOwnedSwitchTarget(
    principal.persona.authProfileId,
    handshake.sourcePrincipalPublicRef,
    handshake.targetPrincipalPublicRef,
  );
  if (!owned) return NextResponse.json({ ok: false, error: 'source and target are not both available to this principal' }, { status: 403 });

  const targetContext = await getActivePersonaByPublicRef(handshake.targetPrincipalPublicRef).catch(() => null);
  if (!targetContext || targetContext.personaId !== owned.target.id) {
    return NextResponse.json({ ok: false, error: 'target persona is not active' }, { status: 409 });
  }
  const grantedScope = rootScopeForTarget(targetContext.cartridgeFlags.isAdmin);
  const safe = {
    source: projectAvailablePersona(owned.source, handshake.sourcePrincipalPublicRef),
    target: projectAvailablePersona(owned.target, handshake.sourcePrincipalPublicRef),
    connectedAgent: handshake.agentAlias,
    requestedScope: grantedScope,
    switchRequiresReauthorization: true,
  };
  if (action === 'inspect') return NextResponse.json({ ok: true, crossing: safe });

  const agreementId = `thr-${handshakeCode}`;
  const formed = await formAgreement(owned.target.id, {
    agreementId,
    displayLabel: `Threshold persona re-crossing → ${handshake.initiatingService}`,
    capabilityRef: `threshold:persona-recross:${handshake.initiatingService}`,
    selectedAgentRef: handshake.agentAlias,
    delegatedAuthority: {
      band: 'L2',
      allowedActions: grantedScope,
      forbiddenActions: FORBIDDEN_ACTIONS,
      allowedSurfaces: ['threshold-gateway'],
      ttlHours: 720,
      maxActions: 1000,
      valueCeiling: null,
    },
    constraints: ['no-redelegation', 'no-money-movement', 'no-identity-disclosure', 'one-session-one-persona'],
    verificationRequirements: ['human-authorized', 'fresh-persona-crossing'],
    settlementTerms: null,
    governingInvariants: ['PRD-THR-001', 'CFS-043'],
  });
  if (!formed.ok) return NextResponse.json({ ok: false, error: `form failed: ${formed.reason}` }, { status: 503 });

  let status = formed.agreement.status;
  if (status === 'proposed') {
    const accepted = await acceptAgreement(owned.target.id, {
      agreementId,
      acceptorType: 'agent',
      acceptorId: handshake.agentAlias,
    });
    if (!accepted.ok) return NextResponse.json({ ok: false, error: `accept failed: ${accepted.reason}` }, { status: 503 });
    status = accepted.agreement.status;
  }
  if (status !== 'authorized') {
    const authorized = await authorizeAgreement(owned.target.id, { agreementId });
    if (!authorized.ok) return NextResponse.json({ ok: false, error: `authorize failed: ${authorized.reason}` }, { status: 403 });
  }

  const issued = await issueAuthorizationCode({
    handshakeCode,
    principalPublicRef: handshake.targetPrincipalPublicRef,
    agentAlias: handshake.agentAlias,
    agreementId,
    grantedScope,
  });
  if ('error' in issued) return NextResponse.json({ ok: false, error: issued.error }, { status: 503 });
  const redirect = new URL(issued.redirectUri);
  redirect.searchParams.set('code', issued.code);
  redirect.searchParams.set('state', handshake.oauthState);
  return NextResponse.json({ ok: true, redirectTo: redirect.toString(), crossing: safe });
}

/**
 * gateway.ts — the metaMe Threshold Gateway catalogue + read-only dispatch
 * (PRD-THR-001 §8). This is the MCP surface the Threshold Companion (the user's
 * agent) speaks to. Increment 1 exposes ONLY the unauthenticated, read-only
 * slice: `list_services`, `inspect_threshold_link`, the discovery resources, and
 * the conversational prompts. The authenticated crossing tools (the
 * Constitutional Handshake, Agent Card, delegation, service entry) are declared
 * in the PRD and land in later increments; they are NOT listed here yet so every
 * advertised tool is functional.
 *
 * Kept dependency-light on purpose (no MCP SDK) — the JSON-RPC transport is a
 * thin hand-rolled handler in app/api/threshold/mcp/route.ts, which keeps the
 * SSR bundle lean (the platform sits near the Amplify output-size cap).
 */

import { createHash } from 'crypto';
import { serviceRegistrySnapshot, listServices, getService, knownCapabilities } from './serviceRegistry';
import { journeyRegistrySnapshot } from './journeyRegistry';
import { buildThresholdLink, type ThresholdLinkManifest } from './thresholdLink';
import { hasScope, type ScopedSession } from './gatewaySession';
import { crossingReceipt, welcomePayload, WELCOME_MESSAGE } from './welcome';
import type { IrlAdapter } from './irlAdapter';
import type { PublicCartridgeId, PublicKnowledgeAdapter } from './publicKnowledge';
import type { CompanionInstallBrief } from '../companion/extensionArtifact';
import type {
  AccessibleIQubeQuery,
  getAccessibleIQube,
  listAccessibleIQubes,
  readAccessibleIQubeText,
} from './personaIQubeProjection';
import { supportedBridgeIds, type NavigatorState } from './constitutionalNavigator';
import {
  fingerprintExchangeArtifact,
  type DepositArtifactMcpArgs,
  type DeclareArtifactFreezeMcpArgs,
  type SignExchangeInstrumentMcpArgs,
  type EstablishDelegationMcpArgs,
  type ConfirmOperatorAssistedArtifactMcpArgs,
  type getExchangeStateForMcp,
  type depositExchangeArtifactViaMcp,
  type declareArtifactFreezeViaMcp,
  type signExchangeInstrumentViaMcp,
  type establishDelegationViaMcp,
  type confirmOperatorAssistedArtifactViaMcp,
  type resolveExchangeWriteAuthority,
} from './mcpConstitutionalActs';
import { decodeBase64Strict } from './uploadContentAsset';
import { AGENT_MANIFEST_URI, agentDiscoveryManifest } from './agentManifest';

// ── Context injected by the route (keeps this module I/O-light + testable) ──

export interface InvitationInfo {
  invitationId: string; // T2-safe id/label — never a raw persona/T0 id
  initiatingService: string;
  institution?: string;
  requestedRole: string;
  requestedCapabilities: string[];
  status: string;
  onboarded: boolean;
  expiresAt?: string | null;
}

export interface GatewayContext {
  origin: string;
  gatewayUrl: string;
  /** Resolve a public capability-URL invitation code to its (T2-safe) metadata. */
  resolveInvitation?: (code: string) => Promise<InvitationInfo | null>;
  /**
   * The scoped session resolved from a presented `Authorization: Bearer` (the
   * Constitutional Handshake bearer), or null/undefined when the Companion is
   * unauthenticated. Additive: Increment 1's read-only tools ignore it; the
   * authenticated crossing tools (later increments) gate on it. Its presence
   * NEVER widens the read-only surface.
   */
  session?: ScopedSession | null;
  /** The IRL read adapter (public open corpus), injected by the route. Present
   *  only where the gateway can reach the app's public routes. */
  irl?: IrlAdapter;
  /**
   * The public knowledge & discovery adapter (2026-09-03) — Qriptopian, IRL
   * OS, AgentiQ OS, and Polity Core's canonically public content, unified
   * behind one small read-only interface. Unauthenticated by design (see
   * PUBLIC_KNOWLEDGE_TOOLS below) — it grants NO execution authority,
   * exposes no private research, and never touches the domain-unscoped
   * embedding pipeline (services/content/embeddingService.ts). See
   * services/threshold/publicKnowledge.ts's own header for the full
   * access-control rationale.
   */
  publicKnowledge?: PublicKnowledgeAdapter;
  /** Begin an incremental service crossing (session upgrade) — returns the human
   *  authorize URL. Injected by the route (creates the upgrade handshake). */
  beginServiceUpgrade?: (service: string, missingCapabilities: string[]) => Promise<{ authorizeUrl: string } | null>;
  /** Owner-safe persona discovery and preparation of a fresh, human-authorized
   * persona crossing. It can never mutate the current session directly. */
  personaRecross?: {
    getState: () => Promise<unknown>;
    listAvailable: () => Promise<unknown[] | null>;
    requestSwitch: (input: { personaPublicRef: string; codeChallenge: string; state: string }) => Promise<
      { ok: true; authorizeUrl: string; expiresAt: string } | { ok: false; error: string }
    >;
  };
  /** Build the Companion install brief (SPEC-MMC-003 §3.2) — the artifact
   *  reference, its integrity values, and the human steps. Injected by the
   *  route because it reads the checked-in extension source from disk; the
   *  gateway module itself stays I/O-light and unit-testable. */
  companionInstall?: () => CompanionInstallBrief;
  /**
   * The composed constitutional-navigator state (2026-08-26) — Passport,
   * sponsorship/delegation, CAS + Reciprocal Exchange grants, and the
   * caller's journey stage, unioned per services/threshold/
   * constitutionalNavigator.ts. Injected by the route (needs the
   * service-role Supabase client and the resolved session) so this module
   * stays I/O-light. `opts.bridge` selects which journey to compose against
   * — see `supportedBridgeIds()` for what's wired.
   */
  resolveNavigatorState?: (opts?: { bridge?: string }) => Promise<NavigatorState | null>;
  /** Persona-scoped global iQube projection. Each call revalidates the live
   *  crossing agreement and delegates the resource decision to the Registry
   *  access spine; this context contains no independent authorization logic. */
  iqubeProjection?: {
    list: (query?: AccessibleIQubeQuery) => ReturnType<typeof listAccessibleIQubes>;
    get: (iqubeId: string) => ReturnType<typeof getAccessibleIQube>;
    readText: (
      iqubeId: string,
      opts?: { offset?: number; limit?: number },
    ) => ReturnType<typeof readAccessibleIQubeText>;
  };
  /**
   * MCP-completable constitutional rituals for the OCSGA / Boundary
   * Research Journey Spine (Surface Independence, 2026-08-26) — injected by
   * the route (needs the service-role Supabase client + the resolved
   * session), each bound to services/threshold/mcpConstitutionalActs.ts's
   * corresponding function. Every one of these calls the SAME canonical
   * service (services/research/reciprocalExchange.ts,
   * services/delegation/delegationGrantStore.ts) the native UI calls —
   * this context only carries the T0<->T2-resolved binding, never a
   * parallel implementation. Absent when no session is resolved.
   */
  mcpActs?: {
    getExchangeState: () => ReturnType<typeof getExchangeStateForMcp>;
    depositArtifact: (args: DepositArtifactMcpArgs) => ReturnType<typeof depositExchangeArtifactViaMcp>;
    declareFreeze: (args: DeclareArtifactFreezeMcpArgs) => ReturnType<typeof declareArtifactFreezeViaMcp>;
    signInstrument: (args: SignExchangeInstrumentMcpArgs) => ReturnType<typeof signExchangeInstrumentViaMcp>;
    establishDelegation: (args: EstablishDelegationMcpArgs) => ReturnType<typeof establishDelegationViaMcp>;
    /** Journey Spine channel convergence (2026-08-28) — adopts a
     *  custodially-registered (operator-assisted) artifact as the bound
     *  principal's own attested evidence. Confirmation-only: never performed
     *  by an operator, never inferred from conversation. */
    confirmOperatorAssistedArtifact: (
      args: ConfirmOperatorAssistedArtifactMcpArgs,
    ) => ReturnType<typeof confirmOperatorAssistedArtifactViaMcp>;
    /**
     * Canonical exchange-write authority probe (2026-08-30, "MCP channel
     * equivalence" repair) — read-only, no side effects. Lets the dispatch
     * gate below authorize deposit/confirm/freeze/sign from REAL exchange
     * participation (Passport + a genuinely bound party on an existing
     * Reciprocal Artifact Exchange) when the session's OAuth-crossing scope
     * alone (`research.exchange.write`) was never separately granted — the
     * SAME resolver every write function already runs internally, so there
     * is exactly one place this authority is decided.
     */
    resolveExchangeAuthority: () => ReturnType<typeof resolveExchangeWriteAuthority>;
  };
}

