/**
 * gatewaySession.ts — the Constitutional Handshake session store (PRD-THR-001 §6).
 *
 * A gateway session is the scoped bearer the Threshold Companion receives after
 * the human crosses. It is bound to an AUTHORIZED Constitutional Agreement and
 * carries only the capability scope the human authorized. This module owns the
 * lifecycle; the authority itself lives in the referenced agreement, and
 * `requireAuthorizedAgreement` remains the enforcement switch (increment 3/4).
 *
 * Guarantees:
 *  - Raw bearers are NEVER stored — only their sha256 hash.
 *  - Only T2 references are stored (principalPublicRef, agentAlias) — no T0 ids.
 *  - resolveBearer is DEFENSIVE: any error (incl. an unmigrated table) degrades
 *    to `null` (unauthenticated), never a 500 — the gateway then serves only the
 *    read-only surface.
 *  - Service-role only (deny-all RLS on the table).
 */

import { createHash, randomBytes, timingSafeEqual } from 'crypto';
import { getSupabaseServer } from '@/app/api/_lib/supabaseServer';
import { grantableCapabilities } from '@/services/threshold/serviceRegistry';

/** Constant-time string equality (security review Finding 8). Length-guarded:
 *  unequal lengths short-circuit false (timingSafeEqual requires equal-length
 *  buffers). Used for the PKCE challenge compare so verification time does not
 *  vary with how many leading characters match. */
function constantTimeEqual(a: string, b: string): boolean {
  const ab = Buffer.from(a);
  const bb = Buffer.from(b);
  if (ab.length !== bb.length) return false;
  return timingSafeEqual(ab, bb);
}

const TABLE = 'agent_gateway_sessions';
const CLIENTS_TABLE = 'agent_gateway_clients';

export interface ScopedSession {
  id: string;
  principalPublicRef: string;
  agentAlias: string;
  agreementId: string | null;
  scope: string[];
  initiatingService: string;
  expiresAt: string | null;
  /** serviceId -> the AUTHORIZED capability-specific agreement id granted by an
   *  incremental service crossing (e.g. irl -> the irl:experiment-result:submit
   *  agreement). The delegated write tools use this, not the base crossing one. */
  serviceAgreements: Record<string, string>;
}

/** Exported unchanged for the Access Gateway human adapter (PRD-PAG-001 §2.1) —
 *  the human-session module MUST share this exact hash encoding so codes/bearers
 *  it writes are resolvable by the shared substrate (exchangeAuthorizationCode
 *  reads auth_code_hash it computes with this same function). */
export function sha256(s: string): string {
  return createHash('sha256').update(s).digest('hex');
}

/** base64url(sha256(x)) — the PKCE S256 transform (RFC 7636). */
function sha256b64url(s: string): string {
  return createHash('sha256').update(s).digest('base64url');
}

/** A url-safe opaque token. Exported unchanged for the Access Gateway human
 *  adapter (PRD-PAG-001 §2.1) — same entropy discipline, one implementation. */
export function newToken(bytes = 32): string {
  return randomBytes(bytes).toString('base64url');
}

/** begin_handshake / OAuth /authorize: create a `pending` row keyed by a one-time
 *  handshake code. When the crossing is driven by the OAuth authorization-code
 *  flow, the client_id / redirect_uri / PKCE challenge / state are bound here so
 *  the eventual code + token exchange is pinned to this exact request. */
export async function createPendingHandshake(input: {
  initiatingService: string;
  requestedScope: string[];
  ttlMinutes?: number;
  clientId?: string;
  redirectUri?: string;
  pkceChallenge?: string;
  oauthState?: string;
}): Promise<{ handshakeCode: string; expiresAt: string } | null> {
  const admin = getSupabaseServer();
  if (!admin) return null;
  const handshakeCode = `thc_${newToken(18)}`;
  const expiresAt = new Date(Date.now() + (input.ttlMinutes ?? 30) * 60_000).toISOString();
  const { error } = await admin.from(TABLE).insert({
    handshake_code: handshakeCode,
    status: 'pending',
    initiating_service: input.initiatingService,
    requested_scope: input.requestedScope,
    client_id: input.clientId ?? null,
    redirect_uri: input.redirectUri ?? null,
    pkce_challenge: input.pkceChallenge ?? null,
    oauth_state: input.oauthState ?? null,
    expires_at: expiresAt,
  });
  if (error) {
    // eslint-disable-next-line no-console
    console.error('[threshold] createPendingHandshake failed:', error.message);
    return null;
  }
  return { handshakeCode, expiresAt };
}

export interface PendingHandshake {
  handshakeCode: string;
  status: string;
  initiatingService: string;
  requestedScope: string[];
  expiresAt: string | null;
}

/** The authorize page reads the pending handshake to show the human what's asked. */
export async function getHandshake(handshakeCode: string): Promise<PendingHandshake | null> {
  const admin = getSupabaseServer();
  if (!admin) return null;
  const { data, error } = await admin
    .from(TABLE)
    .select('handshake_code, status, initiating_service, requested_scope, expires_at')
    .eq('handshake_code', handshakeCode)
    .maybeSingle();
  if (error || !data) return null;
  return {
    handshakeCode: data.handshake_code,
    status: data.status,
    initiatingService: data.initiating_service,
    requestedScope: data.requested_scope ?? [],
    expiresAt: data.expires_at,
  };
}

/**
 * Activate a pending handshake once the human has crossed (Passport + authorized
 * delegation). Mints a bearer, stores only its hash, records the T2 principal +
 * agent + agreement + granted scope, flips to `active`, and returns the raw
 * bearer ONCE. Caller must pass the AUTHORIZED agreement's id + the scope the
 * human actually authorized (never more than requested).
 */
export async function activateHandshake(input: {
  handshakeCode: string;
  principalPublicRef: string;
  agentAlias: string;
  agreementId: string;
  grantedScope: string[];
  sessionTtlDays?: number;
}): Promise<{ bearer: string; expiresAt: string } | null> {
  const admin = getSupabaseServer();
  if (!admin) return null;
  const bearer = `ths_${newToken(32)}`;
  const expiresAt = new Date(Date.now() + (input.sessionTtlDays ?? 30) * 86_400_000).toISOString();
  const { error } = await admin
    .from(TABLE)
    .update({
      token_hash: sha256(bearer),
      status: 'active',
      principal_public_ref: input.principalPublicRef,
      agent_alias: input.agentAlias,
      agreement_id: input.agreementId,
      granted_scope: input.grantedScope,
      expires_at: expiresAt,
    })
    .eq('handshake_code', input.handshakeCode)
    .eq('status', 'pending'); // only a pending handshake can be activated (idempotency guard)
  if (error) {
    // eslint-disable-next-line no-console
    console.error('[threshold] activateHandshake failed:', error.message);
    return null;
  }
  return { bearer, expiresAt };
}

/**
 * The HUMAN crossing act (OAuth authorization step). Called from the browser
 * completion endpoint AFTER the signed-in principal has authorized the
 * Constitutional Agreement. Flips a `pending` handshake to `authorized`, binds
 * the T2 principal + agent + agreement + granted scope, and mints a one-time
 * AUTHORIZATION CODE (returned once). The bearer is NOT minted here — the client
 * exchanges this code (with its PKCE verifier) at the token endpoint. Returns
 * the redirect target so the browser can hand the code back to the Companion.
 */
export async function issueAuthorizationCode(input: {
  handshakeCode: string;
  principalPublicRef: string;
  agentAlias: string;
  agreementId: string;
  grantedScope: string[];
  codeTtlMinutes?: number;
}): Promise<{ code: string; redirectUri: string; oauthState: string | null } | { error: string }> {
  const admin = getSupabaseServer();
  if (!admin) return { error: 'session store unavailable' };
  const { data: row, error: readErr } = await admin
    .from(TABLE)
    .select('status, redirect_uri, oauth_state')
    .eq('handshake_code', input.handshakeCode)
    .maybeSingle();
  if (readErr) return { error: `handshake read failed: ${readErr.message}` };
  if (!row) return { error: 'handshake not found' };
  if (row.status !== 'pending') return { error: `handshake is '${row.status}', not pending` };
  if (!row.redirect_uri) return { error: 'handshake has no bound redirect_uri' };
  const code = `thac_${newToken(32)}`;
  const codeExpiresAt = new Date(Date.now() + (input.codeTtlMinutes ?? 5) * 60_000).toISOString();
  const { data: updated, error } = await admin
    .from(TABLE)
    .update({
      status: 'authorized',
      auth_code_hash: sha256(code),
      code_expires_at: codeExpiresAt,
      principal_public_ref: input.principalPublicRef,
      agent_alias: input.agentAlias,
      agreement_id: input.agreementId,
      granted_scope: input.grantedScope,
    })
    .eq('handshake_code', input.handshakeCode)
    .eq('status', 'pending') // idempotency guard — only a pending row issues a code
    .select('handshake_code');
  if (error) {
    // eslint-disable-next-line no-console
    console.error('[threshold] issueAuthorizationCode update failed:', error.message);
    // Surface the DB reason (e.g. a stale status CHECK constraint that rejects
    // 'authorized') so the crossing is debuggable rather than a blank failure.
    return { error: `code issue update rejected: ${error.message}` };
  }
  if (!updated || updated.length === 0) return { error: 'handshake was no longer pending at update time' };
  return { code, redirectUri: row.redirect_uri, oauthState: row.oauth_state };
}

/**
 * The token endpoint (OAuth authorization-code + PKCE exchange). The Companion
 * presents the authorization code + its PKCE code_verifier + redirect_uri. We
 * verify: code exists, is `authorized`, not expired, redirect_uri matches, and
 * S256(verifier) === stored challenge. Only then do we mint the scoped bearer,
 * store ONLY its hash, flip to `active`, and return the raw bearer ONCE.
 */
export async function exchangeAuthorizationCode(input: {
  code: string;
  codeVerifier: string;
  redirectUri: string;
  sessionTtlDays?: number;
}): Promise<{ bearer: string; scope: string[]; expiresAt: string } | { error: string }> {
  const admin = getSupabaseServer();
  if (!admin) return { error: 'server_error' };
  if (!input.code || !input.codeVerifier) return { error: 'invalid_request' };
  const { data, error } = await admin
    .from(TABLE)
    .select('id, status, redirect_uri, pkce_challenge, code_expires_at, granted_scope, transition_kind, supersedes_session_id')
    .eq('auth_code_hash', sha256(input.code))
    .maybeSingle();
  // Distinct internal reasons are logged (Amplify/CloudWatch) while the client
  // still receives the spec-standard 'invalid_grant' — so a failed exchange is
  // debuggable without leaking which check failed to the caller.
  const reject = (why: string) => {
    // eslint-disable-next-line no-console
    console.error('[threshold] token exchange invalid_grant:', why);
    return { error: 'invalid_grant' as const };
  };
  if (error) return reject(`code read failed: ${error.message}`);
  if (!data) return reject('no row for auth_code');
  if (data.status !== 'authorized') return reject(`status is '${data.status}', not authorized`);
  if (data.code_expires_at && new Date(data.code_expires_at).getTime() < Date.now()) return reject('code expired');
  // redirect_uri must match the one bound at /authorize (trailing slash tolerant).
  const norm = (u: string | null | undefined) => (u ?? '').replace(/\/+$/, '');
  if (norm(data.redirect_uri) !== norm(input.redirectUri)) {
    return reject(`redirect_uri mismatch: bound='${data.redirect_uri}' presented='${input.redirectUri}'`);
  }
  // PKCE S256 proof — the whole point: the code is useless without the verifier.
  // Constant-time compare (Finding 8) so verification time is challenge-independent.
  if (!data.pkce_challenge || !constantTimeEqual(sha256b64url(input.codeVerifier), data.pkce_challenge)) {
    return reject('PKCE verifier does not match challenge');
  }

  const bearer = `ths_${newToken(32)}`;
  const expiresAt = new Date(Date.now() + (input.sessionTtlDays ?? 30) * 86_400_000).toISOString();

  // Persona re-crossing is replacement, never augmentation. Revoke the source
  // before activating the target-bound bearer so no instant can resolve both
  // personas. A retry may continue when a prior attempt revoked the source but
  // failed before target activation; that is fail-closed (temporary no access),
  // never a visibility union.
  if (data.transition_kind === 'persona_switch') {
    if (!data.supersedes_session_id) return reject('persona switch has no source session');
    const { data: source, error: sourceErr } = await admin
      .from(TABLE)
      .select('id, status, expires_at')
      .eq('id', data.supersedes_session_id)
      .maybeSingle();
    if (sourceErr || !source) return reject('persona switch source session not found');
    if (source.expires_at && new Date(source.expires_at).getTime() < Date.now()) return reject('persona switch source session expired');
    if (source.status === 'active') {
      const { data: revoked, error: revokeErr } = await admin
        .from(TABLE)
        .update({ status: 'revoked', revoked_at: new Date().toISOString() })
        .eq('id', source.id)
        .eq('status', 'active')
        .select('id');
      if (revokeErr || !revoked || revoked.length === 0) return reject('source session could not be revoked');
    } else if (source.status !== 'revoked') {
      return reject(`source session status is '${source.status}'`);
    }
  }

  const { data: updated, error: upErr } = await admin
    .from(TABLE)
    .update({
      token_hash: sha256(bearer),
      status: 'active',
      auth_code_hash: null, // one-time: burn the code on exchange
      code_expires_at: null,
      expires_at: expiresAt,
    })
    .eq('id', data.id)
    .eq('status', 'authorized') // guard against code replay / double-exchange
    .select('id');
  if (upErr) {
    // eslint-disable-next-line no-console
    console.error('[threshold] exchangeAuthorizationCode failed:', upErr.message);
    return { error: 'server_error' };
  }
  // The conditional update matched zero rows → another exchange already claimed
  // this code (a replay / race). Do NOT return a bearer that was never stored.
  if (!updated || updated.length === 0) return { error: 'invalid_grant' };
  return { bearer, scope: data.granted_scope ?? [], expiresAt };
}

/** OAuth Dynamic Client Registration (RFC 7591) — public PKCE client, no secret. */
export async function registerClient(input: {
  clientName?: string;
  redirectUris: string[];
}): Promise<{ clientId: string; redirectUris: string[] } | null> {
  const admin = getSupabaseServer();
  if (!admin) return null;
  const redirectUris = (input.redirectUris ?? []).filter((u) => typeof u === 'string' && u.length > 0);
  if (redirectUris.length === 0) return null;
  const clientId = `thc_client_${newToken(16)}`;
  const { error } = await admin.from(CLIENTS_TABLE).insert({
    client_id: clientId,
    client_name: input.clientName ?? null,
    redirect_uris: redirectUris,
  });
  if (error) {
    // eslint-disable-next-line no-console
    console.error('[threshold] registerClient failed:', error.message);
    return null;
  }
  return { clientId, redirectUris };
}

/** Resolve a registered client's redirect allowlist (or null). Defensive. */
export async function getClient(clientId: string | null | undefined): Promise<{ clientId: string; redirectUris: string[] } | null> {
  if (!clientId) return null;
  try {
    const admin = getSupabaseServer();
    if (!admin) return null;
    const { data, error } = await admin
      .from(CLIENTS_TABLE)
      .select('client_id, redirect_uris')
      .eq('client_id', clientId)
      .maybeSingle();
    if (error || !data) return null;
    return { clientId: data.client_id, redirectUris: data.redirect_uris ?? [] };
  } catch {
    return null;
  }
}

/** Resolve a presented bearer to its scoped session (or null). Defensive. */
export async function resolveBearer(bearer: string | null | undefined): Promise<ScopedSession | null> {
  if (!bearer) return null;
  try {
    const admin = getSupabaseServer();
    if (!admin) return null;
    const { data, error } = await admin
      .from(TABLE)
      .select('id, status, principal_public_ref, agent_alias, agreement_id, granted_scope, initiating_service, expires_at, service_agreements')
      .eq('token_hash', sha256(bearer))
      .maybeSingle();
    if (error || !data) return null;
    if (data.status !== 'active') return null;
    if (data.expires_at && new Date(data.expires_at).getTime() < Date.now()) return null;
    // best-effort touch (never blocks resolution)
    void admin.from(TABLE).update({ last_used_at: new Date().toISOString() }).eq('id', data.id);
    return {
      id: data.id,
      principalPublicRef: data.principal_public_ref,
      agentAlias: data.agent_alias,
      agreementId: data.agreement_id,
      scope: data.granted_scope ?? [],
      initiatingService: data.initiating_service,
      expiresAt: data.expires_at,
      serviceAgreements: (data.service_agreements as Record<string, string> | null) ?? {},
    };
  } catch (e) {
    // eslint-disable-next-line no-console
    console.error('[threshold] resolveBearer degraded to unauthenticated:', e instanceof Error ? e.message : e);
    return null;
  }
}

export async function revokeByHandshake(handshakeCode: string): Promise<boolean> {
  const admin = getSupabaseServer();
  if (!admin) return false;
  const { error } = await admin
    .from(TABLE)
    .update({ status: 'revoked', revoked_at: new Date().toISOString() })
    .eq('handshake_code', handshakeCode);
  return !error;
}

export interface PersonaSwitchHandshake {
  handshakeCode: string;
  status: string;
  sourceSessionId: string;
  sourcePrincipalPublicRef: string;
  targetPrincipalPublicRef: string;
  agentAlias: string;
  initiatingService: string;
  requestedScope: string[];
  oauthState: string | null;
  expiresAt: string | null;
}

/** Prepare a short-lived persona re-crossing pinned to the active bearer and
 * its registered OAuth client/redirect. This does not mutate the source session. */
export async function createPersonaSwitchHandshake(input: {
  source: ScopedSession;
  targetPrincipalPublicRef: string;
  requestedScope: string[];
  pkceChallenge: string;
  oauthState: string;
  ttlMinutes?: number;
}): Promise<{ handshakeCode: string; expiresAt: string } | { error: string }> {
  const admin = getSupabaseServer();
  if (!admin) return { error: 'session store unavailable' };
  if (!/^[A-Za-z0-9_-]{43,128}$/.test(input.pkceChallenge)) return { error: 'a valid PKCE S256 codeChallenge is required' };
  if (!input.oauthState.trim()) return { error: 'state is required for persona re-crossing' };
  const { data: source, error: sourceError } = await admin
    .from(TABLE)
    .select('id,status,client_id,redirect_uri,initiating_service,principal_public_ref,agent_alias')
    .eq('id', input.source.id)
    .maybeSingle();
  if (sourceError || !source || source.status !== 'active') return { error: 'source session is not active' };
  if (!source.client_id || !source.redirect_uri) return { error: 'source session is not bound to an OAuth client' };
  if (source.principal_public_ref !== input.source.principalPublicRef || source.agent_alias !== input.source.agentAlias) {
    return { error: 'source session binding changed' };
  }

  const handshakeCode = `thp_${newToken(18)}`;
  const expiresAt = new Date(Date.now() + (input.ttlMinutes ?? 10) * 60_000).toISOString();
  const { error } = await admin.from(TABLE).insert({
    handshake_code: handshakeCode,
    status: 'pending',
    initiating_service: source.initiating_service,
    requested_scope: input.requestedScope,
    client_id: source.client_id,
    redirect_uri: source.redirect_uri,
    pkce_challenge: input.pkceChallenge,
    oauth_state: input.oauthState,
    transition_kind: 'persona_switch',
    supersedes_session_id: source.id,
    target_principal_public_ref: input.targetPrincipalPublicRef,
    expires_at: expiresAt,
    // Deliberately empty: service authority never crosses a persona boundary.
    service_agreements: {},
  });
  if (error) return { error: `persona switch preparation failed: ${error.message}` };
  return { handshakeCode, expiresAt };
}

export async function getPersonaSwitchHandshake(handshakeCode: string): Promise<PersonaSwitchHandshake | null> {
  const admin = getSupabaseServer();
  if (!admin) return null;
  const { data, error } = await admin
    .from(TABLE)
    .select('handshake_code,status,supersedes_session_id,target_principal_public_ref,initiating_service,requested_scope,oauth_state,expires_at')
    .eq('handshake_code', handshakeCode)
    .eq('transition_kind', 'persona_switch')
    .maybeSingle();
  if (error || !data?.supersedes_session_id || !data.target_principal_public_ref) return null;
  const { data: source } = await admin
    .from(TABLE)
    .select('principal_public_ref,agent_alias,status,expires_at')
    .eq('id', data.supersedes_session_id)
    .maybeSingle();
  if (!source?.principal_public_ref || !source.agent_alias || source.status !== 'active') return null;
  if (source.expires_at && new Date(source.expires_at).getTime() < Date.now()) return null;
  return {
    handshakeCode: data.handshake_code,
    status: data.status,
    sourceSessionId: data.supersedes_session_id,
    sourcePrincipalPublicRef: source.principal_public_ref,
    targetPrincipalPublicRef: data.target_principal_public_ref,
    agentAlias: source.agent_alias,
    initiatingService: data.initiating_service,
    requestedScope: data.requested_scope ?? [],
    oauthState: data.oauth_state,
    expiresAt: data.expires_at,
  };
}

// ── Incremental service crossing (session upgrade — Increment 4b) ────────────

/** Begin an incremental service crossing: a `pending` handshake pinned to the
 *  ACTIVE session it will upgrade. The human authorizes the service delegation in
 *  the browser; on success `applyUpgrade` augments that same session (no new
 *  bearer is minted). */
export async function createUpgradeHandshake(input: {
  parentSessionId: string;
  service: string;
  requestedScope: string[];
  ttlMinutes?: number;
}): Promise<{ handshakeCode: string; expiresAt: string } | null> {
  const admin = getSupabaseServer();
  if (!admin) return null;
  const handshakeCode = `thu_${newToken(18)}`;
  const expiresAt = new Date(Date.now() + (input.ttlMinutes ?? 30) * 60_000).toISOString();
  const { error } = await admin.from(TABLE).insert({
    handshake_code: handshakeCode,
    status: 'pending',
    initiating_service: input.service,
    requested_scope: input.requestedScope,
    upgrade_of: input.parentSessionId,
    transition_kind: 'service_upgrade',
    expires_at: expiresAt,
  });
  if (error) {
    // eslint-disable-next-line no-console
    console.error('[threshold] createUpgradeHandshake failed:', error.message);
    return null;
  }
  return { handshakeCode, expiresAt };
}

export interface UpgradeHandshake {
  handshakeCode: string;
  status: string;
  service: string;
  requestedScope: string[];
  parentSessionId: string | null;
  expiresAt: string | null;
}

/** The upgrade authorize page reads what's being asked + which session it augments. */
export async function getUpgradeHandshake(handshakeCode: string): Promise<UpgradeHandshake | null> {
  const admin = getSupabaseServer();
  if (!admin) return null;
  const { data, error } = await admin
    .from(TABLE)
    .select('handshake_code, status, initiating_service, requested_scope, upgrade_of, expires_at')
    .eq('handshake_code', handshakeCode)
    .maybeSingle();
  if (error || !data || !data.upgrade_of) return null; // an upgrade handshake MUST be pinned to a parent
  return {
    handshakeCode: data.handshake_code,
    status: data.status,
    service: data.initiating_service,
    requestedScope: data.requested_scope ?? [],
    parentSessionId: data.upgrade_of,
    expiresAt: data.expires_at,
  };
}

/** Apply an authorized incremental crossing: UNION the granted scope into the
 *  parent session and record the service's authorized agreement — then close the
 *  upgrade handshake. The parent's existing bearer now carries the new authority.
 *  Idempotency-guarded on the pending upgrade handshake. */
export async function applyUpgrade(input: {
  handshakeCode: string;
  agreementId: string;
  grantedScope: string[];
}): Promise<{ ok: true } | { ok: false; error: string }> {
  const admin = getSupabaseServer();
  if (!admin) return { ok: false, error: 'session store unavailable' };
  const hs = await getUpgradeHandshake(input.handshakeCode);
  if (!hs) return { ok: false, error: 'upgrade handshake not found' };
  if (hs.status !== 'pending') return { ok: false, error: `upgrade is '${hs.status}', not pending` };
  if (!hs.parentSessionId) return { ok: false, error: 'upgrade handshake has no parent session' };

  // Read the parent's current scope + service map, then union in the new grant.
  const { data: parent, error: pErr } = await admin
    .from(TABLE)
    .select('id, status, granted_scope, service_agreements')
    .eq('id', hs.parentSessionId)
    .maybeSingle();
  if (pErr || !parent) return { ok: false, error: 'parent session not found' };
  if (parent.status !== 'active') return { ok: false, error: 'parent session is not active' };

  // Defense-in-depth (security review Finding 7): re-validate the granted scope
  // against what the service is actually allowed to grant, INSIDE applyUpgrade —
  // never trust the caller to have clamped it. Any capability outside the
  // service's grantable set is dropped before it can union into a live bearer.
  const grantable = grantableCapabilities(hs.service);
  const safeGranted = input.grantedScope.filter((c) => grantable.has(c));

  const nextScope = Array.from(new Set([...(parent.granted_scope ?? []), ...safeGranted]));
  const nextAgreements = { ...((parent.service_agreements as Record<string, string> | null) ?? {}), [hs.service]: input.agreementId };

  const up = await admin
    .from(TABLE)
    .update({ granted_scope: nextScope, service_agreements: nextAgreements })
    .eq('id', hs.parentSessionId)
    .eq('status', 'active');
  if (up.error) return { ok: false, error: `upgrade apply failed: ${up.error.message}` };

  // Close the upgrade handshake to a TERMINAL status (Finding 7) — 'revoked', not
  // 'active'. The row has a null token_hash so it never resolves as a bearer, but
  // it must not linger as an `active`-status row; this also guards against replay.
  const close = await admin
    .from(TABLE)
    .update({ status: 'revoked', agreement_id: input.agreementId, granted_scope: safeGranted })
    .eq('handshake_code', input.handshakeCode)
    .eq('status', 'pending');
  if (close.error) return { ok: false, error: `upgrade close failed: ${close.error.message}` };
  return { ok: true };
}

/** Pure scope check — a session may perform an action iff its granted scope
 *  contains the capability (exact or a `prefix.*` wildcard grant). */
export function hasScope(session: ScopedSession | null, capability: string): boolean {
  if (!session) return false;
  return session.scope.some((s) => s === capability || (s.endsWith('.*') && capability.startsWith(s.slice(0, -1))));
}

import type { ScopedSession } from './gatewaySession';
import { createPersonaSwitchHandshake } from './gatewaySession';
import { getActivePersonaByPublicRef } from '@/services/identity/getActivePersona';
import { containsRawIdentifier, personaPublicRef } from '@/services/identity/personaReferences';
import { getAgreement } from '@/services/constitutional/constitutionalAgreement';
import { getSupabaseServer } from '@/app/api/_lib/supabaseServer';
import { listVisiblePersonaInventory, type PersonaInventoryRow } from '@/services/wallet/personaInventory';
import { CONSTITUTIONAL_ROOT_CAPABILITIES } from './serviceRegistry';
import { normalizeThresholdScope } from './requireThresholdSession';

export type AvailablePersona = {
  personaPublicRef: string;
  displayLabel: string;
  fioHandle: string | null;
  appOrigin: string | null;
  status: string;
  isCurrent: boolean;
};

export function projectAvailablePersona(row: PersonaInventoryRow, currentRef: string): AvailablePersona {
  const publicRef = personaPublicRef(row.id);
  return {
    personaPublicRef: publicRef,
    displayLabel: row.display_name || row.fio_handle || 'Unnamed persona',
    // This is the owner/delegate's bounded self-inventory, not public discovery.
    fioHandle: row.fio_handle || null,
    appOrigin: row.app_origin || null,
    status: row.status,
    isCurrent: publicRef === currentRef,
  };
}

export function rootScopeForTarget(isAdmin: boolean): string[] {
  return normalizeThresholdScope(
    CONSTITUTIONAL_ROOT_CAPABILITIES.filter((capability) => capability !== 'content.asset.upload' || isAdmin),
  );
}

export function selectAvailablePersona(
  rows: PersonaInventoryRow[],
  targetRef: string,
  currentRef: string,
): PersonaInventoryRow | null {
  if (!targetRef || containsRawIdentifier(targetRef) || targetRef === currentRef) return null;
  return rows.find((row) => personaPublicRef(row.id) === targetRef) ?? null;
}

async function inventoryForSession(session: ScopedSession): Promise<{
  activePersona: NonNullable<Awaited<ReturnType<typeof getActivePersonaByPublicRef>>>;
  rows: PersonaInventoryRow[];
} | null> {
  const admin = getSupabaseServer();
  if (!admin) return null;
  const activePersona = await getActivePersonaByPublicRef(session.principalPublicRef).catch(() => null);
  if (!activePersona) return null;
  const rows = await listVisiblePersonaInventory(admin, { callerAuthProfileId: activePersona.authProfileId }).catch(() => []);
  // A session only gets discovery if its exact bound persona is still visible
  // under the canonical wallet ownership policy.
  if (!rows.some((row) => personaPublicRef(row.id) === session.principalPublicRef)) return null;
  return { activePersona, rows };
}

export async function getPersonaState(session: ScopedSession) {
  const inventory = await inventoryForSession(session);
  const current = inventory?.rows.find((row) => personaPublicRef(row.id) === session.principalPublicRef) ?? null;
  const agreement = session.agreementId ? await getAgreement(session.agreementId) : null;
  return {
    principalPublicRef: session.principalPublicRef,
    displayLabel: current?.display_name || current?.fio_handle || null,
    fioHandle: current?.fio_handle || null,
    personaResolved: Boolean(inventory?.activePersona && current),
    agreement: session.agreementId
      ? { agreementRef: session.agreementId, status: agreement?.status ?? 'unresolved' }
      : null,
    currentScope: [...session.scope],
    switchRequiresReauthorization: true as const,
  };
}

export async function listAvailablePersonas(session: ScopedSession): Promise<AvailablePersona[] | null> {
  const inventory = await inventoryForSession(session);
  if (!inventory) return null;
  return inventory.rows.map((row) => projectAvailablePersona(row, session.principalPublicRef));
}

export async function requestPersonaSwitch(
  session: ScopedSession,
  input: { personaPublicRef: string; codeChallenge: string; state: string },
  origin: string,
): Promise<{ ok: true; authorizeUrl: string; expiresAt: string } | { ok: false; error: string }> {
  const targetRef = input.personaPublicRef.trim();
  const oauthState = input.state;
  if (!oauthState.trim()) return { ok: false, error: 'state is required for persona re-crossing.' };
  if (!targetRef || containsRawIdentifier(targetRef)) {
    return { ok: false, error: 'personaPublicRef must be a T2 Polity Public Reference; raw persona identifiers are refused.' };
  }
  if (targetRef === session.principalPublicRef) return { ok: false, error: 'That persona is already bound to this crossing.' };
  const inventory = await inventoryForSession(session);
  if (!inventory) return { ok: false, error: 'The current persona binding could not be resolved.' };
  const targetRow = selectAvailablePersona(inventory.rows, targetRef, session.principalPublicRef);
  if (!targetRow) return { ok: false, error: 'That persona is not available to this principal.' };
  const target = await getActivePersonaByPublicRef(targetRef).catch(() => null);
  if (!target || target.personaId !== targetRow.id) return { ok: false, error: 'The target persona is not active.' };

  const prepared = await createPersonaSwitchHandshake({
    source: session,
    targetPrincipalPublicRef: targetRef,
    requestedScope: rootScopeForTarget(target.cartridgeFlags.isAdmin),
    pkceChallenge: input.codeChallenge,
    oauthState,
  });
  if ('error' in prepared) return { ok: false, error: prepared.error };
  return {
    ok: true,
    authorizeUrl: `${origin}/threshold/switch-persona#code=${encodeURIComponent(prepared.handshakeCode)}`,
    expiresAt: prepared.expiresAt,
  };
}

/** Browser-authorized owner check shared by inspection and approval. */
export async function resolveOwnedSwitchTarget(authProfileId: string, sourceRef: string, targetRef: string) {
  const admin = getSupabaseServer();
  if (!admin) return null;
  const rows = await listVisiblePersonaInventory(admin, { callerAuthProfileId: authProfileId }).catch(() => []);
  const source = rows.find((row) => personaPublicRef(row.id) === sourceRef) ?? null;
  const target = rows.find((row) => personaPublicRef(row.id) === targetRef) ?? null;
  return source && target ? { source, target } : null;
}

