/**
 * Shared, T2-safe vocabulary for Threshold discovery projections.
 *
 * Domain registries remain canonical for their own records. These types only
 * describe how those records are presented to an external agent, so public
 * knowledge, iQube Cards, IRL invariants, and service discovery can converge
 * without creating a second registry or a second maturity vocabulary.
 */

export type DiscoverySourceAuthority =
  | 'ratified-canon'
  | 'normative-specification'
  | 'implemented-system-documentation'
  | 'operational-state'
  | 'experimental-evidence'
  | 'proposed-work'
  | 'explanatory-commentary'
  | 'historical-or-deprecated';

export type DiscoveryOpenness =
  | 'public-spec'
  | 'public-source'
  | 'public-document'
  | 'public-registry'
  | 'authenticated'
  | 'persona-restricted'
  | 'confidential-bilateral'
  | 'cohort-restricted'
  | 'proprietary-implementation';

export type DiscoveryMaturity =
  | 'ratified'
  | 'implemented'
  | 'operational'
  | 'demonstrated'
  | 'experimental'
  | 'proposed'
  | 'projected'
  | 'historical'
  | 'deprecated';

export type McpExposure = 'available-now' | 'native-only' | 'implemented-not-exposed' | 'preview' | 'planned' | 'deprecated';

export interface DiscoveryReference {
  label: string;
  /** MCP resource URI, tool name, public URL, or repository/path reference. */
  ref: string;
  authority: DiscoverySourceAuthority;
}

export interface DiscoveryDescriptor {
  id: string;
  name: string;
  description: string;
  layer: 'constitutional' | 'identity' | 'protocol' | 'registry' | 'runtime' | 'development' | 'research' | 'public-knowledge' | 'bridge';
  openness: DiscoveryOpenness[];
  maturity: DiscoveryMaturity[];
  mcpExposure: McpExposure;
  canonicalSources: DiscoveryReference[];
  mcpRoutes: string[];
  accessRequirements: string[];
  implementationNote?: string;
}

export const SOURCE_PRECEDENCE: DiscoverySourceAuthority[] = [
  'ratified-canon',
  'normative-specification',
  'implemented-system-documentation',
  'operational-state',
  'experimental-evidence',
  'proposed-work',
  'explanatory-commentary',
  'historical-or-deprecated',
];

import { describe, expect, it } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import {
  extractThresholdBearer,
  normalizeThresholdScope,
} from '@/services/threshold/requireThresholdSession';

const THRESHOLD_ROUTES = path.join(process.cwd(), 'app', 'api', 'threshold');
const BROWSER_AUTH_ALLOWLIST = new Set([
  // HUMAN authorization act: this route intentionally resolves canonical
  // persona authority before projecting it into a Threshold bearer.
  path.normalize('oauth/complete/route.ts'),
  // HUMAN persona re-crossing act: this completion route must resolve the
  // signed-in owner's source and target personas before issuing a fresh,
  // target-bound Threshold authorization code. It never mutates the existing
  // MCP session or acts from agent-held authority.
  path.normalize('persona-switch/complete/route.ts'),
]);

function routeFiles(dir: string): string[] {
  const files: string[] = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const absolute = path.join(dir, entry.name);
    if (entry.isDirectory()) files.push(...routeFiles(absolute));
    else if (/\.(ts|tsx)$/.test(entry.name)) files.push(absolute);
  }
  return files;
}

describe('Threshold authentication invariant', () => {
  it('extracts Bearer credentials case-insensitively', () => {
    const headers = new Headers({ authorization: 'bEaReR ths_example_token' });
    expect(extractThresholdBearer({ headers })).toBe('ths_example_token');
  });

  it('rejects absent or non-Bearer authorization headers', () => {
    expect(extractThresholdBearer({ headers: new Headers() })).toBeNull();
    expect(extractThresholdBearer({ headers: new Headers({ authorization: 'Basic abc' }) })).toBeNull();
  });

  it('normalizes minted capability scope without changing order', () => {
    expect(normalizeThresholdScope([
      'passport.status.read',
      'content.asset.upload',
      'content.asset.upload',
      ' research.read ',
      '',
      'passport.status.read',
    ])).toEqual([
      'passport.status.read',
      'content.asset.upload',
      'research.read',
    ]);
  });

  it('forbids browser/persona auth adapters in Threshold action routes', () => {
    const offenders: string[] = [];
    for (const file of routeFiles(THRESHOLD_ROUTES)) {
      const relative = path.normalize(path.relative(THRESHOLD_ROUTES, file));
      if (BROWSER_AUTH_ALLOWLIST.has(relative)) continue;
      const source = fs.readFileSync(file, 'utf8');
      if (/from\s+['"]@\/services\/identity\/getActivePersona['"]/.test(source)) {
        offenders.push(relative);
      }
    }
    expect(offenders).toEqual([]);
  });

  it('keeps native upload action on the canonical Threshold auth adapter', () => {
    const file = path.join(THRESHOLD_ROUTES, 'upload-action', 'route.ts');
    const source = fs.readFileSync(file, 'utf8');
    expect(source).toContain("requireThresholdSession(req, 'content.asset.upload')");
    expect(source).not.toMatch(/from\s+['"]@\/services\/identity\/getActivePersona['"]/);
  });
});

import { describe, expect, it, vi } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import { personaPublicRef } from '../services/identity/personaReferences';
import {
  projectAvailablePersona,
  rootScopeForTarget,
  selectAvailablePersona,
} from '../services/threshold/personaRecross';
import { callTool, HANDSHAKE_TOOLS, listTools } from '../services/threshold/gateway';
import type { PersonaInventoryRow } from '../services/wallet/personaInventory';
import type { ScopedSession } from '../services/threshold/gatewaySession';

const uuidA = '11111111-1111-4111-8111-111111111111';
const uuidB = '22222222-2222-4222-8222-222222222222';
const row = (id: string, label: string): PersonaInventoryRow => ({
  id,
  tenant_id: '33333333-3333-4333-8333-333333333333',
  auth_profile_id: '44444444-4444-4444-8444-444444444444',
  display_name: label,
  avatar_uri: null,
  fio_handle: `${label.toLowerCase()}@metame`,
  fio_domain: null,
  discoverable_within_tenant: false,
  reputation_score: 0,
  reputation_bucket: 0,
  badges: [],
  default_identity_state: null,
  world_id_status: null,
  app_origin: 'metame',
  status: 'active',
  created_at: '2026-09-10T00:00:00Z',
  updated_at: '2026-09-10T00:00:00Z',
});

const session: ScopedSession = {
  id: 'session-server-id',
  principalPublicRef: personaPublicRef(uuidA),
  agentAlias: 'companion_safe',
  agreementId: 'thr-safe',
  scope: ['iqube.read'],
  initiatingService: 'ocsga',
  expiresAt: null,
  serviceAgreements: { ocsga: 'must-not-transfer' },
};

describe('Issue #112 — bounded persona discovery and re-crossing', () => {
  it('advertises all three authenticated tools and challenges bearer-less calls', () => {
    const tools = listTools();
    const names = tools.map((tool) => tool.name);
    expect(names).toEqual(expect.arrayContaining(['get_persona_state', 'list_available_personas', 'request_persona_switch']));
    expect(HANDSHAKE_TOOLS.has('request_persona_switch')).toBe(true);
    const switchTool = tools.find((tool) => tool.name === 'request_persona_switch');
    expect(switchTool?.inputSchema.required).toContain('state');
  });

  it('projects only T2 and owner-safe fields', () => {
    const projected = projectAvailablePersona(row(uuidB, 'Party A'), session.principalPublicRef);
    expect(projected.personaPublicRef).toBe(personaPublicRef(uuidB));
    expect(JSON.stringify(projected)).not.toContain(uuidB);
    expect(JSON.stringify(projected)).not.toContain('tenant_id');
    expect(JSON.stringify(projected)).not.toContain('auth_profile_id');
  });

  it('rejects raw, current, and foreign targets within the already-scoped inventory', () => {
    const rows = [row(uuidA, 'Source'), row(uuidB, 'Party A')];
    expect(selectAvailablePersona(rows, uuidB, session.principalPublicRef)).toBeNull();
    expect(selectAvailablePersona(rows, session.principalPublicRef, session.principalPublicRef)).toBeNull();
    expect(selectAvailablePersona(rows, 'ffffffffffffffff', session.principalPublicRef)).toBeNull();
    expect(selectAvailablePersona(rows, personaPublicRef(uuidB), session.principalPublicRef)?.id).toBe(uuidB);
  });

  it('recomputes root scope and never transfers an old admin cap to a non-admin target', () => {
    expect(rootScopeForTarget(false)).toContain('iqube.read');
    expect(rootScopeForTarget(false)).not.toContain('content.asset.upload');
    expect(rootScopeForTarget(true)).toContain('content.asset.upload');
  });

  it('dispatches discovery and preparation without changing the current session object', async () => {
    const before = structuredClone(session);
    const requestSwitch = vi.fn().mockResolvedValue({ ok: true, authorizeUrl: 'https://example.test/threshold/switch-persona#code=safe', expiresAt: 'soon' });
    const context = {
      origin: 'https://example.test',
      gatewayUrl: 'https://example.test/api/threshold/mcp',
      session,
      personaRecross: {
        getState: vi.fn(),
        listAvailable: vi.fn().mockResolvedValue([]),
        requestSwitch,
      },
    };
    const result = await callTool('request_persona_switch', {
      personaPublicRef: personaPublicRef(uuidB),
      codeChallenge: 'a'.repeat(43),
      codeChallengeMethod: 'S256',
      state: 'client-correlation-state',
    }, context);
    expect(result).not.toHaveProperty('isError');
    expect(requestSwitch).toHaveBeenCalledOnce();
    expect(requestSwitch).toHaveBeenCalledWith(expect.objectContaining({ state: 'client-correlation-state' }));
    expect(session).toEqual(before);
  });

  it('rejects a persona re-crossing without OAuth state before preparing a handshake', async () => {
    const requestSwitch = vi.fn();
    const result = await callTool('request_persona_switch', {
      personaPublicRef: personaPublicRef(uuidB),
      codeChallenge: 'a'.repeat(43),
      codeChallengeMethod: 'S256',
    }, {
      origin: 'https://example.test',
      gatewayUrl: 'https://example.test/api/threshold/mcp',
      session,
      personaRecross: {
        getState: vi.fn(),
        listAvailable: vi.fn(),
        requestSwitch,
      },
    });
    expect(result.isError).toBe(true);
    expect(requestSwitch).not.toHaveBeenCalled();
  });

  it('structurally enforces fresh-session replacement and no service-agreement carryover', () => {
    const source = fs.readFileSync(path.join(process.cwd(), 'services/threshold/gatewaySession.ts'), 'utf8');
    const createStart = source.indexOf('export async function createPersonaSwitchHandshake');
    const createEnd = source.indexOf('export async function getPersonaSwitchHandshake');
    const createBody = source.slice(createStart, createEnd);
    expect(createBody).toContain("transition_kind: 'persona_switch'");
    expect(createBody).toContain('supersedes_session_id: source.id');
    expect(createBody).toContain('service_agreements: {}');
    expect(createBody).not.toContain('.update(');

    const exchangeStart = source.indexOf('export async function exchangeAuthorizationCode');
    const exchangeEnd = source.indexOf('/** OAuth Dynamic Client Registration');
    const exchange = source.slice(exchangeStart, exchangeEnd);
    expect(exchange.indexOf("status: 'revoked'")).toBeLessThan(exchange.indexOf("status: 'active'"));
  });

  it('fails closed at browser completion when persisted OAuth state is absent', () => {
    const source = fs.readFileSync(path.join(process.cwd(), 'app/api/threshold/persona-switch/complete/route.ts'), 'utf8');
    expect(source).toMatch(/if \(!handshake\.oauthState\?\.trim\(\)\)/);
    expect(source).toMatch(/persona switch state missing; request a fresh crossing/);
    expect(source).toContain("redirect.searchParams.set('state', handshake.oauthState)");
    expect(source).not.toMatch(/if \(issued\.oauthState\)/);
  });

  it('binds browser approval to the target persona and a new agreement', () => {
    const route = fs.readFileSync(path.join(process.cwd(), 'app/api/threshold/persona-switch/complete/route.ts'), 'utf8');
    expect(route).toContain('resolveOwnedSwitchTarget');
    expect(route).toContain('formAgreement(owned.target.id');
    expect(route).toContain('principalPublicRef: handshake.targetPrincipalPublicRef');
    expect(route).not.toContain('applyUpgrade');
  });
});

import { describe, expect, it } from 'vitest';
import { AGENT_MANIFEST_URI, agentDiscoveryManifest } from '../services/threshold/agentManifest';
import { listResources, readResource, type GatewayContext } from '../services/threshold/gateway';

const bareCtx: GatewayContext = { origin: 'http://localhost:3000', gatewayUrl: 'http://localhost:3000/api/threshold/mcp' };

describe('Threshold canonical agent discovery manifest', () => {
  it('is the first listed resource and is public without an authenticated session', async () => {
    expect(listResources()[0].uri).toBe(AGENT_MANIFEST_URI);
    const result = await readResource(AGENT_MANIFEST_URI, bareCtx);
    expect(result.isError).not.toBe(true);
    expect(JSON.parse(result.contents[0].text)).toEqual(agentDiscoveryManifest());
  });

  it('declares source precedence and the required constitutional distinctions', () => {
    const manifest = agentDiscoveryManifest();
    expect(manifest.sourcePrecedence[0]).toBe('ratified-canon');
    expect(manifest.sourcePrecedence.at(-1)).toBe('historical-or-deprecated');
    expect(manifest.distinctions).toContain('Personhood != Identity != Persona');
    expect(manifest.distinctions).toContain('Authorization != Payload disclosure');
    expect(manifest.distinctions).toContain('Registry existence != Resource readability');
    expect(manifest.distinctions).toContain('Implemented != MCP-exposed');
  });

  it('routes every component to at least one source and MCP route without treating implementation absence as non-existence', () => {
    for (const component of agentDiscoveryManifest().components) {
      expect(component.canonicalSources.length).toBeGreaterThan(0);
      expect(component.mcpRoutes.length).toBeGreaterThan(0);
      expect(component.accessRequirements.length).toBeGreaterThan(0);
    }
    expect(agentDiscoveryManifest().components.find((entry) => entry.id === 'agentiq-nanos')?.mcpExposure).toBe('implemented-not-exposed');
  });
});
